#!/usr/bin/env node
/**
 * 멤버 프로필 사진 시드
 * node scripts/seed-profiles.mjs
 */
import admin from "firebase-admin";

process.env.FIRESTORE_EMULATOR_HOST = process.env.FIRESTORE_EMULATOR_HOST ?? "localhost:8080";
admin.initializeApp({ projectId: "trip-planner-2026-ec5ec" });
const db = admin.firestore();

const PROFILES = {
  "xdiqN6R92NbFXjf2zB8y0xdTB0Ky": { displayName: "나라",  photoURL: "data:image/jpeg;base64," },
  "uid_yujin_2026_trip":          { displayName: "유진",  photoURL: "data:image/jpeg;base64," },
  "uid_sojeong_2026_trip":        { displayName: "소정",  photoURL: "data:image/jpeg;base64," },
  "uid_seonghui_2026_trip":       { displayName: "성희",  photoURL: "data:image/jpeg;base64," },
};

async function main() {
  console.log("👤 멤버 프로필 사진 저장 중...\n");
  for (const [uid, data] of Object.entries(PROFILES)) {
    await db.collection("userProfiles").doc(uid).set(data, { merge: true });
    console.log(`  ✅ ${data.displayName} (${uid.slice(0,16)}...)`);
  }
  console.log("\n🎉 완료! 홈화면에서 멤버 사진을 확인해보세요.");
  process.exit(0);
}
main().catch(e => { console.error("❌", e.message); process.exit(1); });
